text:
{
  "osszkep": "A szöveg alapvetően közvetlen és követhető, de néhány helyen túlságosan szakmai, darabos vagy a beszélt nyelvben szokatlan szófordulatokat használ. Kis simításokkal még természetesebb, emberibb és megnyugtatóbb lesz a hangvétel.",
  "javaslatok": [
    {
      "id": "L01",
      "gond": "Kissé gépies és távolságtartó nyitás; a 'telepítetted az alkalmazásunkat' helyett természetesebb az 'alkalmazást' forma vagy a letöltés említése.",
      "uj_szoveg": "Örülünk, hogy letöltötted az alkalmazást!"
    },
    {
      "id": "L07",
      "gond": "A 'bekötés' belső szakzsargon, egy laikusnak vagy idősebb vállalkozónak idegenül és technikaian hangzik.",
      "uj_szoveg": "A beállítás csak néhány lépés. Mindegyiknél leírtuk, mit kell tenned, miért fontos, és hol találod."
    },
    {
      "id": "L11",
      "gond": "A 'megadod a kártyádat' kifejezés rideg, kissé pontatlan (a kártyaadatokat adja meg).",
      "uj_szoveg": "Elfogadod a szerződést, és beállítod a bankkártyádat a havidíjhoz."
    },
    {
      "id": "L13",
      "gond": "A 'NAV-meghatalmazás' összetétel hivataloskodó, beszédben természetesebben hangzik kibontva.",
      "uj_szoveg": "Ezután meghatalmazást adsz a könyvelődnek a NAV-nál. Ebben is segít az alkalmazás."
    },
    {
      "id": "L15",
      "gond": "A 'lakcímkártyád lakcímes oldalát' kifejezés szóismétlő és nehezen kimondható beszélt nyelven.",
      "uj_szoveg": "Lefotózod a személyidet, és a lakcímkártyád hátoldalát."
    },
    {
      "id": "L16",
      "gond": "A megfogalmazás bürokratikus és szigorú; egy privátbanki stílusban érdemesebb megnyugtatóan jelezni a kötelező jogi hátteret.",
      "uj_szoveg": "Erre a törvényi előírások miatt van szükség."
    },
    {
      "id": "L18",
      "gond": "A 'funkció még nem érhető el' informatikai műszó, a 60 éves felhasználónak kevésbé kézzelfogható.",
      "uj_szoveg": "Addig néhány dolgot még nem érsz el, de utána minden megnyílik."
    },
    {
      "id": "L20",
      "gond": "A '24–48 órán belül' kimondva hosszú és hivatali ízű, barátságosabb az 1-2 napos megfogalmazás.",
      "uj_szoveg": "Ha elakadsz, kérj visszahívást, és csapatunk egy-két napon belül keresni fog."
    }
  ]
}
